public with sharing class EntitlementExpiryQueue implements Queueable {
    private Set<Id> entitlementIds;

    public EntitlementExpiryQueue(Set<Id> entitlementIds) {
        this.entitlementIds = entitlementIds == null
            ? new Set<Id>()
            : new Set<Id>(entitlementIds);
    }

    public void execute(QueueableContext context) {
        List<Entitlement__c> selected = [
            SELECT Id, State__c
            FROM Entitlement__c
            WHERE Id IN :entitlementIds
        ];
        for (Entitlement__c entitlement : selected) {
            entitlement.State__c = 'Expired';
        }
        if (!selected.isEmpty()) {
            update selected;
        }
    }
}

@IsTest
public class EntitlementExpiryQueueTest {
    @IsTest
    static void expiredEntriesAreMarked() {
        Entitlement__c expired = new Entitlement__c(
            Expires_On__c = Date.today().addDays(-1),
            State__c = 'Active'
        );
        insert expired;

        Test.startTest();
        System.enqueueJob(new EntitlementExpiryQueue(new Set<Id>{ expired.Id }));
        Test.stopTest();

        Entitlement__c saved = [
            SELECT State__c
            FROM Entitlement__c
            WHERE Id = :expired.Id
        ];
        System.assertEquals('Expired', saved.State__c);
    }
}

